ALTER TABLE users ADD COLUMN IF NOT EXISTS status ENUM('active', 'inactive') DEFAULT 'active' NOT NULL AFTER role;
ALTER TABLE users ADD COLUMN IF NOT EXISTS resetToken VARCHAR(255) AFTER lastSignedIn;
ALTER TABLE users ADD COLUMN IF NOT EXISTS resetTokenExpires TIMESTAMP AFTER resetToken;
ALTER TABLE users MODIFY COLUMN lastSignedIn TIMESTAMP NULL DEFAULT NULL;
ALTER TABLE users MODIFY COLUMN passwordHash VARCHAR(255) NOT NULL;
ALTER TABLE users MODIFY COLUMN username VARCHAR(255) NOT NULL UNIQUE;
ALTER TABLE users MODIFY COLUMN name TEXT NOT NULL;
ALTER TABLE users MODIFY COLUMN email VARCHAR(320) NOT NULL;

